import React from 'react';

const Statistics = () => {
  return (
    <div>
      <h1 className="text-2xl font-bold mb-6">Statistiques</h1>
      <div className="card">
        <p>Les statistiques globales seront affichees ici.</p>
      </div>
    </div>
  );
};

export default Statistics;
